import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<number>} [position]
 * @property {Array<number>} [rotation]
 * @property {Array<number>} [scale]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Object} [textContent]
 * @property {Array<any>} [neighbors]
 * @property {Object} [visual]
 * @property {Array<any>} [behavior]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Object3D} glbLoader
 * @property {(event:string, payload?:any)=>void} [emit]
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 */

/**
 * Creates the ornamental divider node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// Root container
	const root = new THREE.Object3D();

	// Load GLB (synchronous via cached loader)
	const glbUrl = config.meshUrl || '/prism-mock/home/nodes/cta-hero.glb';
	const glb = ctx.glbLoader(glbUrl);
	const mesh = glb.clone(true);
	root.add(mesh);

	// Apply transform
	const pos = config.position || [-2.5, 0.7, 0];
	const rot = config.rotation || [0, 0, 0];
	const scl = config.scale || [1, 1, 1];
	root.position.set(pos[0], pos[1], pos[2]);
	root.rotation.set(rot[0], rot[1], rot[2]);
	root.scale.set(scl[0], scl[1], scl[2]);

	// Apply cinematic primitives if any
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		}
	}

	// Interaction state
	const originalY = root.position.y;
	let riseTween = null;
	let pressTween = null;

	// Hover handlers
	function onHoverEnter() {
		if (riseTween) riseTween.kill();
		riseTween = gsap.to(root.position, {
			y: originalY + 0.15,
			duration: 0.7,
			ease: 'power3.out',
		});
	}
	function onHoverLeave() {
		if (riseTween) riseTween.kill();
		riseTween = gsap.to(root.position, {
			y: originalY,
			duration: 0.7,
			ease: 'power3.out',
		});
	}

	// Click handler (press-down + emit)
	function onClick() {
		if (pressTween) pressTween.kill();
		pressTween = gsap.to(root.scale, {
			x: 0.97,
			y: 0.97,
			z: 0.97,
			duration: 0.12,
			ease: 'back.out(1.7)',
			onComplete: () => {
				gsap.to(root.scale, {
					x: 1,
					y: 1,
					z: 1,
					duration: 0.12,
					ease: 'power2.out',
				});
			},
		});

		if (typeof ctx.emit === 'function') {
			ctx.emit('hub-home.select');
		}
	}

	// Data binding placeholder (no concrete implementation)
	const dataBindings = [
		{
			source: 'trpc.visits.book.slot',
			target: 'confirmPanel',
		},
	];

	// Cleanup routine
	function cleanup() {
		// Dispose geometries and materials
		root.traverse((child) => {
			if (child.isMesh) {
				if (child.geometry) child.geometry.dispose();
				if (Array.isArray(child.material)) {
					child.material.forEach((m) => m && m.dispose && m.dispose());
				} else if (child.material) {
					child.material.dispose();
				}
			}
		});

		// Kill GSAP tweens
		if (riseTween) riseTween.kill();
		if (pressTween) pressTween.kill();

		// Remove references
		root.removeFromParent();
	}

	// Attach handlers and cleanup to userData
	root.userData = {
		handlers: {
			hoverEnter: onHoverEnter,
			hoverLeave: onHoverLeave,
			click: onClick,
		},
		cleanup,
		dataBindings,
	};

	return root;
}
